-- Optional catalog upgrade for an existing database with the original NOTIFICATION V1.
-- Metadata only: fixed-runtime event handling and Sidecar commands are unchanged.
-- Run after deploying the corrected resource; never rewrite V1 or running snapshots.
-- Reserved V2 id: 820000000000000033. Check id/checksum conflicts before execution.
START TRANSACTION;
SELECT id,current_version FROM fcc_flow_definition
WHERE flow_key='SYSTEM_NOTIFICATION' FOR UPDATE;

INSERT INTO fcc_flow_definition_version
(id,flow_definition_id,version_no,definition_json,checksum,publish_status,published_at,created_by)
SELECT 820000000000000033,d.id,2,CONVERT( USING utf8mb4),
'9e029565801809756625ddf42405682f11d23e1bd89272570d86218d4c2b0b4a','DRAFT',NULL,'system-model-repair'
FROM fcc_flow_definition d
JOIN fcc_flow_definition_version old ON old.flow_definition_id=d.id AND old.version_no=1
WHERE d.flow_key='SYSTEM_NOTIFICATION' AND d.model_type='NOTIFICATION'
  AND d.current_version=1 AND old.checksum='93e695ac177c725c4ad16ef3604a38eda97e07433ed11d4ab16f13a06da5d638'
  AND NOT EXISTS (SELECT 1 FROM fcc_flow_definition_version v WHERE v.flow_definition_id=d.id AND v.version_no=2);

-- Release the one-published unique marker before publishing V2, in the same transaction.
UPDATE fcc_flow_definition_version old
JOIN fcc_flow_definition d ON d.id=old.flow_definition_id
JOIN fcc_flow_definition_version v ON v.flow_definition_id=d.id AND v.version_no=2
SET old.publish_status='ARCHIVED'
WHERE d.flow_key='SYSTEM_NOTIFICATION' AND d.model_type='NOTIFICATION'
  AND d.current_version=1 AND old.version_no=1
  AND old.checksum='93e695ac177c725c4ad16ef3604a38eda97e07433ed11d4ab16f13a06da5d638'
  AND old.publish_status='PUBLISHED'
  AND v.checksum='9e029565801809756625ddf42405682f11d23e1bd89272570d86218d4c2b0b4a'
  AND v.publish_status IN ('DRAFT','PUBLISHED');

UPDATE fcc_flow_definition_version v
JOIN fcc_flow_definition d ON d.id=v.flow_definition_id
JOIN fcc_flow_definition_version old ON old.flow_definition_id=d.id AND old.version_no=1
SET v.publish_status='PUBLISHED',v.published_at=UTC_TIMESTAMP(3)
WHERE d.flow_key='SYSTEM_NOTIFICATION' AND d.model_type='NOTIFICATION'
  AND d.current_version=1 AND old.publish_status='ARCHIVED'
  AND old.checksum='93e695ac177c725c4ad16ef3604a38eda97e07433ed11d4ab16f13a06da5d638'
  AND v.version_no=2 AND v.publish_status='DRAFT'
  AND v.checksum='9e029565801809756625ddf42405682f11d23e1bd89272570d86218d4c2b0b4a';

UPDATE fcc_flow_definition d
JOIN fcc_flow_definition_version v ON v.flow_definition_id=d.id AND v.version_no=2
JOIN fcc_flow_definition_version old ON old.flow_definition_id=d.id AND old.version_no=1
SET d.current_version=2
WHERE d.flow_key='SYSTEM_NOTIFICATION' AND d.model_type='NOTIFICATION'
  AND d.current_version=1 AND old.checksum='93e695ac177c725c4ad16ef3604a38eda97e07433ed11d4ab16f13a06da5d638'
  AND v.checksum='9e029565801809756625ddf42405682f11d23e1bd89272570d86218d4c2b0b4a' AND v.publish_status='PUBLISHED';
COMMIT;

-- Verify: no row or a nonmatching checksum requires manual review, never force overwrite.
SELECT d.flow_key,d.current_version,v.version_no,v.checksum
FROM fcc_flow_definition d JOIN fcc_flow_definition_version v
ON v.flow_definition_id=d.id AND v.version_no=d.current_version
WHERE d.flow_key='SYSTEM_NOTIFICATION';

-- Stop and ROLLBACK on any SQL error; never run with mysql --force.
-- Repair/rollback: retain V2 and all call snapshots. Under a definition row lock,
-- verify current_version=2 and both expected checksums, then archive V2,
-- republish V1 and switch current_version=1 in one transaction. Reload runtime cache.
